async function checkToken(rpc, address) {
  const call = async (data) => {
    const res = await fetch(rpc, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "eth_call", params: [{ to: address, data }, "latest"] })
    });
    return (await res.json()).result;
  };
  const hexToString = (hex) => {
    if (!hex || hex === "0x") return "";
    let str = "";
    for (let i = 2; i < hex.length; i += 2) {
      const code = parseInt(hex.substr(i, 2), 16);
      if (code > 31 && code < 127) str += String.fromCharCode(code);
    }
    return str.trim();
  };
  const sym = await call("0x95d89b41");
  const name = await call("0x06fdde03");
  console.log(address, "symbol:", hexToString(sym), "name:", hexToString(name));
}

async function run() {
  console.log("Arbitrum One:");
  await checkToken("https://arb1.arbitrum.io/rpc", "0x82aF49447D8a07e3bd95BD0d56f35241523fBab1");
  await checkToken("https://arb1.arbitrum.io/rpc", "0xaf88d065e77c8cC2239327C5EDb3A432268e5831");
  await checkToken("https://arb1.arbitrum.io/rpc", "0xFF970A61A04b1cA14834A43f5dE4533eBDDB5CC8");

  console.log("Arbitrum Sepolia:");
  await checkToken("https://sepolia-rollup.arbitrum.io/rpc", "0x980B62Da83eff3D4576C647993b0c1D7faf17c73");
  await checkToken("https://sepolia-rollup.arbitrum.io/rpc", "0x75faf114eafb1BDbe2F0316DF893fd58CE46AA4d");
}
run();
'

