async function test() {
  const rpc = "https://sepolia-rollup.arbitrum.io/rpc";
  const call = async (to, data) => {
    const res = await fetch(rpc, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "eth_call", params: [{ to, data }, "latest"] })
    });
    return (await res.json()).result;
  };
  const hexToString = (hex) => {
    if (!hex || hex === "0x") return "";
    let str = "";
    for (let i = 2; i < hex.length; i += 2) {
      const code = parseInt(hex.substr(i, 2), 16);
      if (code > 31 && code < 127) str += String.fromCharCode(code);
    }
    return str.trim();
  };
  const sym = await call("0x119f0e6303bec7021b295ecab27a4a1a5b37ecf0", "0x95d89b41");
  const name = await call("0x119f0e6303bec7021b295ecab27a4a1a5b37ecf0", "0x06fdde03");
  console.log("symbol:", hexToString(sym), "name:", hexToString(name));
}
test();
'

