node -e '
const fs = require("fs");
const content = fs.readFileSync("config.json", "utf8");
try {
  const json = JSON.parse(content);
  console.log("JSON parsed successfully");
  console.log("Keys:", Object.keys(json));
  console.log("Production chain:", json.networkConfig.environments.production.chain);
  console.log("Staging chain:", json.networkConfig.environments.staging.chain);
} catch (e) {
  console.error("JSON parse error:", e);
  process.exit(1);
}
'

